"use client"

import { useState, useEffect } from "react"
import { useAuth } from "@/components/auth-provider"
import { useDictionary } from "@/components/dictionary-provider"
import { createClient } from "@/lib/supabase"
import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import { UserCog, ShieldCheck, ShieldAlert, Save, X, Trash2 } from "lucide-react"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogFooter
} from "@/components/ui/dialog"
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from "@/components/ui/select"

export default function UsersPage() {
  const { dict } = useDictionary()
  const { profile, loading: authLoading } = useAuth()
  const supabase = createClient()
  
  const [users, setUsers] = useState<any[]>([])
  const [roles, setRoles] = useState<string[]>([])
  const [loading, setLoading] = useState(true)
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [editingUser, setEditingUser] = useState<any>(null)

  const modules = ['companies', 'products', 'quotes', 'orders', 'shipments', 'invoices']
  const actions = ['view', 'insert', 'edit', 'delete', 'print']

  async function fetchData() {
    try {
      setLoading(true)
      const [userRes, roleRes] = await Promise.all([
        supabase.from('profiles').select('*').order('created_at'),
        supabase.from('role_permissions').select('role')
      ])
      
      if (userRes.error) console.error("User fetch error:", userRes.error)
      if (roleRes.error) console.error("Role fetch error:", roleRes.error)

      if (userRes.data) setUsers(userRes.data)
      if (roleRes.data) setRoles(roleRes.data.map(r => r.role))
    } catch (err) {
      console.error("Fetch data unexpected error:", err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (profile) {
      fetchData()
    }
  }, [profile])

  const handleEdit = (user: any) => {
    setEditingUser({ ...user })
    setIsDialogOpen(true)
  }

  const handlePermissionChange = (module: string, action: string, value: boolean) => {
    const updatedPermissions = { ...editingUser.permissions }
    if (!updatedPermissions[module]) {
      updatedPermissions[module] = { view: false, insert: false, edit: false, delete: false, print: false }
    }
    updatedPermissions[module][action] = value
    setEditingUser({ ...editingUser, permissions: updatedPermissions })
  }

  const handleRoleChange = async (role: string) => {
    const { data: roleInfo } = await supabase
      .from('role_permissions')
      .select('permissions')
      .eq('role', role)
      .single()
    
    setEditingUser({ 
      ...editingUser, 
      role, 
      permissions: roleInfo?.permissions || editingUser.permissions 
    })
  }

  const handleSave = async () => {
    const { error } = await supabase
      .from('profiles')
      .update({
        role: editingUser.role,
        permissions: editingUser.permissions,
        is_active: editingUser.is_active,
        full_name: editingUser.full_name,
        phone: editingUser.phone
      })
      .eq('id', editingUser.id)

    if (!error) {
      setIsDialogOpen(false)
      fetchData()
    }
  }

  if (authLoading) {
    return (
      <div className="p-8 text-center flex flex-col items-center justify-center min-h-[400px]">
        <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-muted-foreground">{dict.LOADING}</p>
      </div>
    )
  }

  console.log("UsersPage: Current profile role:", profile?.role)

  if (profile?.role !== 'admin' && profile?.role !== 'manager') {
    return <div className="p-8 text-center">{dict.MSG_ACCESS_DENIED}</div>
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <h1 className="page-title">{dict.TITLE_USER_MGMT}</h1>
      </div>

      <Card className="data-card">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>{dict.LABEL_USER}</TableHead>
              <TableHead>{dict.LABEL_PHONE_SHORT}</TableHead>
              <TableHead>{dict.LABEL_ROLE}</TableHead>
              <TableHead>{dict.LABEL_STATUS}</TableHead>
              <TableHead>Last Login</TableHead>
              <TableHead className="text-right">{dict.LABEL_ACTIONS}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow><TableCell colSpan={6} className="text-center py-8">{dict.LOADING}</TableCell></TableRow>
            ) : users.length === 0 ? (
              <TableRow><TableCell colSpan={6} className="text-center py-8">{dict.NO_DATA}</TableCell></TableRow>
            ) : (
              users.map((u) => (
                <TableRow key={u.id}>
                  <TableCell>
                    <div className="flex flex-col">
                      <span className="font-medium">{u.full_name}</span>
                      <span className="text-xs text-muted-foreground">{u.username} | {u.email}</span>
                    </div>
                  </TableCell>
                  <TableCell className="text-sm">{u.phone || '-'}</TableCell>
                  <TableCell>
                    <span className="capitalize px-2 py-1 rounded-full bg-secondary text-xs font-semibold">
                      {u.role}
                    </span>
                  </TableCell>
                  <TableCell>
                    {u.is_active ? (
                      <div className="flex items-center text-success text-xs font-medium">
                        <ShieldCheck className="size-3 mr-1" /> {dict.LABEL_APPROVED}
                      </div>
                    ) : (
                      <div className="flex items-center text-warning text-xs font-medium">
                        <ShieldAlert className="size-3 mr-1" /> {dict.LABEL_PENDING}
                      </div>
                    )}
                  </TableCell>
                  <TableCell className="text-xs text-muted-foreground">
                    {u.last_login ? new Date(u.last_login).toLocaleString() : '-'}
                  </TableCell>
                  <TableCell className="text-right">
                    <Button variant="ghost" size="sm" onClick={() => handleEdit(u)}>
                      <UserCog className="size-4 mr-2" />
                      {dict.BUTTON_MANAGE}
                    </Button>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{dict.TITLE_MANAGE_USER}: {editingUser?.full_name}</DialogTitle>
          </DialogHeader>
          
          <div className="grid gap-6 py-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="flex flex-col gap-2">
                <Label>{dict.LABEL_FULL_NAME}</Label>
                <Input 
                  value={editingUser?.full_name || ""} 
                  onChange={(e) => setEditingUser({ ...editingUser, full_name: e.target.value })}
                />
              </div>
              <div className="flex flex-col gap-2">
                <Label>{dict.LABEL_PHONE}</Label>
                <Input 
                  value={editingUser?.phone || ""} 
                  onChange={(e) => setEditingUser({ ...editingUser, phone: e.target.value })}
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="flex flex-col gap-2">
                <Label>{dict.LABEL_ROLE}</Label>
                <Select value={editingUser?.role} onValueChange={handleRoleChange}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {roles.map(r => <SelectItem key={r} value={r} className="capitalize">{r}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
              <div className="flex flex-col gap-2">
                <Label>Username</Label>
                <Input 
                  value={editingUser?.username || ""} 
                  disabled
                  className="bg-muted"
                />
              </div>
            </div>

            <div className="flex items-center gap-4 p-4 border rounded-lg bg-muted/30">
              <div className="flex-1">
                <h3 className="font-semibold text-sm">{dict.LABEL_ACC_APPROVAL}</h3>
                <p className="text-xs text-muted-foreground">{dict.DESC_ACC_APPROVAL}</p>
              </div>
              <Button 
                variant={editingUser?.is_active ? "outline" : "default"}
                onClick={() => setEditingUser({ ...editingUser, is_active: !editingUser.is_active })}
              >
                {editingUser?.is_active ? dict.BUTTON_REVOKE : dict.BUTTON_APPROVE}
              </Button>
            </div>

            <div className="flex flex-col gap-4">
              <h3 className="font-bold border-b pb-2">{dict.LABEL_GRANULAR_PERMS}</h3>
              <div className="grid grid-cols-[150px_repeat(5,1fr)] gap-2 text-center text-xs font-bold text-muted-foreground mb-2">
                <div className="text-left">{dict.LABEL_MODULE}</div>
                {actions.map(a => <div key={a} className="capitalize">{a}</div>)}
              </div>
              
              {modules.map(m => (
                <div key={m} className="grid grid-cols-[150px_repeat(5,1fr)] gap-2 items-center border-b border-muted py-2 hover:bg-muted/10">
                  <div className="text-sm font-medium capitalize">{m}</div>
                  {actions.map(a => (
                    <div key={a} className="flex justify-center">
                      <input 
                        type="checkbox"
                        className="size-4 cursor-pointer accent-primary"
                        checked={editingUser?.permissions?.[m]?.[a] || false}
                        onChange={(e) => handlePermissionChange(m, a, e.target.checked)}
                      />
                    </div>
                  ))}
                </div>
              ))}
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              <X className="mr-2 size-4" /> {dict.BUTTON_CANCEL}
            </Button>
            <Button onClick={handleSave}>
              <Save className="mr-2 size-4" /> {dict.BUTTON_SAVE}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}